public class Main {
    static int digitSum(int n) {
        if (n < 10) return n;
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return digitSum(sum);
    }
    public static void main(String[] args) {
        System.out.print(digitSum(987654));
    }
}

